using BARANG.Core.Api.Errors;
using BARANG.Core.Application.Abstractions.Correlation;
using BARANG.Core.Application.Files;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Files;
using BARANG.Core.Domain.Security;
using Microsoft.AspNetCore.Mvc;

namespace BARANG.Core.Api.Files;

public static class ArtworkFileEndpoints
{
    public static IEndpointRouteBuilder MapArtworkFileEndpoints(this IEndpointRouteBuilder endpoints)
    {
        RouteGroupBuilder artworks=endpoints.MapGroup("/api/v1/artworks");RouteGroupBuilder artworkRead=artworks.MapGroup("").RequireAuthorization(SecurityPermissions.ArtworkRead);artworkRead.MapGet("/",async(string?search,string?categoryCode,bool?includeArchived,int?pageNumber,int?pageSize,int?limit,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.SearchArtworksAsync(search,categoryCode,includeArchived??false,pageNumber??1,pageSize??limit??20,ct)));artworkRead.MapGet("/concept-search",async(string?q,int?limit,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ConceptSearchArtworksAsync(q,limit??36,ct)));artworkRead.MapGet("/options",async(string?search,int?limit,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ArtworkOptionsAsync(search,limit??20,ct)));artworkRead.MapGet("/{id:guid}",async(Guid id,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.GetArtworkAsync(id,ct)));artworkRead.MapGet("/{id:guid}/versions",async(Guid id,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ListArtworkVersionsAsync(id,ct)));artworkRead.MapGet("/{id:guid}/history",async(Guid id,int? pageNumber,int? pageSize,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ListArtworkHistoryAsync(id,pageNumber??1,pageSize??100,ct)));artworkRead.MapGet("/{id:guid}/original",async(Guid id,IArtworkFileAdministration s,CancellationToken ct)=>{Result<DownloadFile> result=await s.GetOriginalArtworkAsync(id,ct);return result.IsFailure?Problem(result.Error):Results.Stream(result.Value.Content,result.Value.MediaType,result.Value.FileName);});artworkRead.MapGet("/{id:guid}/thumbnail",async(Guid id,IArtworkFileAdministration s,CancellationToken ct)=>{Result<DownloadFile> result=await s.GetThumbnailAsync(id,ct);return result.IsFailure?Problem(result.Error):Results.Stream(result.Value.Content,result.Value.MediaType,result.Value.FileName);});
        RouteGroupBuilder artworkManage=artworks.MapGroup("").RequireAuthorization(SecurityPermissions.ArtworkManage);artworkManage.MapPost("/",async(ArtworkRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.CreateArtworkAsync(r.Command(),ct),true));artworkManage.MapPut("/{id:guid}",async(Guid id,ArtworkRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.UpdateArtworkAsync(id,r.Command(),ct)));artworkManage.MapPost("/{id:guid}/archive",async(Guid id,ArchiveRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ArchiveArtworkAsync(id,r.Archived,r.Version,ct)));artworkManage.MapPost("/{id:guid}/versions",async(Guid id,ArtworkVersionRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.CreateArtworkVersionAsync(id,r.FileVersionId,r.Notes,ct),true));artworkManage.MapPost("/{id:guid}/tags/{tagId:guid}",async(Guid id,Guid tagId,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.AssignTagAsync(id,tagId,ct),true));
        RouteGroupBuilder tags=endpoints.MapGroup("/api/v1/artwork-tags").RequireAuthorization(SecurityPermissions.ArtworkManage);tags.MapPost("/",async(TagRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.CreateTagAsync(r.Code,r.DisplayName,ct),true));tags.MapPut("/{id:guid}",async(Guid id,TagRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.UpdateTagAsync(id,r.DisplayName,r.IsActive,r.Version,ct)));
        RouteGroupBuilder files=endpoints.MapGroup("/api/v1/files");files.MapPost("/upload",UploadAsync).RequireAuthorization(SecurityPermissions.FileUpload).DisableAntiforgery();RouteGroupBuilder fileRead=files.MapGroup("").RequireAuthorization(SecurityPermissions.FileRead);fileRead.MapGet("/{id:guid}",async(Guid id,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.GetFileAsync(id,ct)));fileRead.MapGet("/{id:guid}/versions/{versionId:guid}/download",DownloadAsync);RouteGroupBuilder fileManage=files.MapGroup("").RequireAuthorization(SecurityPermissions.FileManage);fileManage.MapPost("/{id:guid}/archive",async(Guid id,ArchiveRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.ArchiveFileAsync(id,r.Version,ct)));fileManage.MapPost("/{id:guid}/links",async(Guid id,FileLinkRequest r,IArtworkFileAdministration s,CancellationToken ct)=>Map(await s.LinkFileAsync(id,r.FileVersionId,r.EntityType,r.EntityId,r.Purpose,ct),true));return endpoints;
    }
    private static async Task<IResult>UploadAsync(HttpRequest request,IArtworkFileAdministration service,CancellationToken ct){if(!request.HasFormContentType)return Results.BadRequest();IFormCollection form=await request.ReadFormAsync(ct);IFormFile?file=form.Files.GetFile("file");if(file is null)return Results.BadRequest();Guid?fileId=Guid.TryParse(form["fileId"],out Guid id)?id:null;await using Stream stream=file.OpenReadStream();return Map(await service.UploadAsync(new(fileId,file.FileName,file.ContentType,file.Length,stream,form["sha256"]),ct),true);}
    private static async Task<IResult>DownloadAsync(Guid id,Guid versionId,IArtworkFileAdministration service,CancellationToken ct){Result<DownloadFile>result=await service.DownloadAsync(id,versionId,ct);return result.IsFailure?Map(result):Results.Stream(result.Value.Content,result.Value.MediaType,result.Value.FileName,enableRangeProcessing:false);}
    private static IResult Map<T>(Result<T> result,bool created=false)=>result.IsSuccess?Results.Json(result.Value,statusCode:created?201:200):Problem(result.Error);
    private static IResult Problem(Error error){ProblemDetails p=ApiProblemDetailsMapper.Create(error,"unavailable",null);return Results.Problem(p.Detail,p.Instance,p.Status,p.Title,extensions:p.Extensions);}
}
public sealed record ArtworkRequest(string Code,string Title,string?Description,string?CategoryCode,Guid?DesignerUserId,string LifecycleStatus="Draft",long Version=0){public ArtworkCommand Command()=>new(Code,Title,Description,CategoryCode,DesignerUserId,LifecycleStatus,Version);}
public sealed record ArtworkVersionRequest(Guid FileVersionId,string?Notes);public sealed record ArchiveRequest(bool Archived,long Version);public sealed record TagRequest(string Code,string DisplayName,bool IsActive=true,long Version=0);public sealed record FileLinkRequest(Guid?FileVersionId,FileLinkEntityType EntityType,Guid EntityId,FileLinkPurpose Purpose);
